<script setup>
import { computed, onMounted, ref } from 'vue'
import { apiRequest } from '../services/api'
const users=ref([]),loading=ref(false),busy=ref(false),error=ref(''),show=ref(false),editing=ref(null),form=ref({fullName:'',email:'',password:'',position:'Инженер-лаборант',department:'Метрологическая служба',isActive:true})
const engineers=computed(()=>users.value.filter(x=>x.role==='engineer'))
async function load(){loading.value=true;error.value='';try{const data=await apiRequest('users');users.value=Array.isArray(data)?data:data.items||[]}catch(e){error.value=e.message||'Не удалось загрузить инженеров'}finally{loading.value=false}}
function add(){editing.value=null;form.value={fullName:'',email:'',password:'',position:'Инженер-лаборант',department:'Метрологическая служба',isActive:true};show.value=true}
function edit(item){editing.value=item;form.value={fullName:item.fullName||'',email:item.email||'',password:'',position:item.position||'Инженер-лаборант',department:item.department||'Метрологическая служба',isActive:item.isActive!==false};show.value=true}
async function save(){busy.value=true;error.value='';try{if(editing.value){const payload={...form.value};if(!payload.password)delete payload.password;const updated=await apiRequest(`users/${editing.value.id}`,{method:'PATCH',body:JSON.stringify(payload)});Object.assign(editing.value,updated||payload)}else{const created=await apiRequest('register',{method:'POST',body:JSON.stringify({...form.value,role:'engineer'})});users.value.push(created.user||created)}show.value=false}catch(e){error.value=e.message||'Не удалось сохранить инженера'}finally{busy.value=false}}
async function remove(item){if(!confirm(`Удалить пользователя «${item.fullName}»?`))return;busy.value=true;error.value='';try{await apiRequest(`users/${item.id}`,{method:'DELETE'});users.value=users.value.filter(x=>x.id!==item.id)}catch(e){error.value=e.message||'Не удалось удалить инженера'}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="page"><div class="section-heading"><div><h2>Инженеры-лаборанты</h2><p>Добавляйте, редактируйте и удаляйте учётные записи инженеров.</p></div><button class="btn-primary" @click="add">＋ Добавить инженера</button></div><p v-if="error" class="auth-error">{{error}}</p><div class="table-panel"><table class="data-table"><thead><tr><th>СОТРУДНИК</th><th>ЭЛЕКТРОННАЯ ПОЧТА</th><th>ПОДРАЗДЕЛЕНИЕ</th><th>СТАТУС</th><th>ДЕЙСТВИЯ</th></tr></thead><tbody><tr v-for="item in engineers" :key="item.id"><td>{{item.fullName}}<small class="muted" style="display:block;font-weight:400;margin-top:3px">{{item.position||'Инженер-лаборант'}}</small></td><td>{{item.email}}</td><td>{{item.department||'—'}}</td><td><span :class="['status',item.isActive===false?'overdue':'active']">{{item.isActive===false?'Отключён':'Активен'}}</span></td><td><button class="btn-outline" @click="edit(item)">Изменить</button> <button class="btn-outline" @click="remove(item)">Удалить</button></td></tr><tr v-if="!engineers.length"><td colspan="5" class="empty">{{loading?'Загрузка пользователей…':'Инженеры-лаборанты не найдены'}}</td></tr></tbody></table></div><div v-if="show" class="modal-backdrop" @click.self="show=false"><form class="modal" @submit.prevent="save"><h2>{{editing?'Редактирование инженера':'Новый инженер-лаборант'}}</h2><div class="form-grid"><label class="field full">ФИО<input v-model.trim="form.fullName" required placeholder="Иванов Иван Иванович"></label><label class="field">Электронная почта<input v-model.trim="form.email" required type="email" placeholder="engineer@company.ru"></label><label class="field">Пароль <span v-if="editing" class="muted">(оставьте пустым, чтобы не менять)</span><input v-model="form.password" :required="!editing" :minlength="form.password?6:0" type="password" placeholder="Минимум 6 символов"></label><label class="field">Должность<input v-model.trim="form.position"></label><label class="field">Подразделение<input v-model.trim="form.department"></label></div><p v-if="error" class="auth-error">{{error}}</p><div class="modal-actions"><button type="button" class="btn-outline" @click="show=false">Отмена</button><button class="btn-primary" :disabled="busy">{{busy?'Сохранение…':'Сохранить'}}</button></div></form></div></section></template>
